{prodSetting.key} = ${prodSetting.value} (label: ${prodSetting.label})`,\r\n    );\r\n\r\n    // 4. Get a setting by key and print its value\r\n    const retrieved: ConfigurationSetting = await client.getConfigurationSetting({\r\n      key: \"app:Settings:FontSize\",\r\n    });\r\n    console.log(`Retrieved setting: ${retrieved.key} = ${retrieved.value}`);\r\n\r\n    // 5. List all settings matching a key filter\r\n    console.log(\"\\nSettings matching 'app:Settings:*':\");\r\n    const settingsIterator = client.listConfigurationSettings({\r\n      keyFilter: \"app:Settings:*\",\r\n    });\r\n    for await (const setting of settingsIterator) {\r\n      console.log(`  ${setting.key} = ${setting.value} (label: ${setting.label ?? \"(none)\"})`);\r\n    }\r\n\r\n    // 6. Create a feature flag configuration setting\r\n    const featureFlagId = `${featureFlagPrefix}BetaFeature`;\r\n    const featureFlag: ConfigurationSetting = await client.setConfigurationSetting({\r\n      key: featureFlagId,\r\n      contentType: featureFlagContentType,\r\n      value: JSON.stringify({\r\n        id: \"BetaFeature\",\r\n        description: \"Controls access to beta features\",\r\n        enabled: true,\r\n        conditions: { client_filters: [] },\r\n      }),\r\n    });\r\n    console.log(`\\nCreated feature flag: ${featureFlag.key}`);\r\n\r\n    // 7. Delete the setting by key\r\n    await client.deleteConfigurationSetting({ key: \"app:Settings:FontSize\" });\r\n    console.log(\"\\nDeleted setting: app:Settings:FontSize (no label)\");\r\n\r\n    // Clean up: delete the labeled setting and feature flag\r\n    await client.deleteConfigurationSetting({\r\n      key: \"app:Settings:FontSize\",\r\n      label: \"Production\",\r\n    });\r\n    await client.deleteConfigurationSetting({ key: featureFlagId });\r\n    console.log(\"Cleaned up remaining settings.\");\r\n  } catch (error: unknown) {\r\n    if (error instanceof RestError) {\r\n      console.error(`Azure REST error: ${error.message}`);\r\n      console.error(`  Status code: ${error.statusCode}`);\r\n      console.error(`  Request ID: ${error.request?.headers?.get(\"x-ms-client-request-id\")}`);\r\n    } else if (error instanceof Error) {\r\n      console.error(`Unexpected error: ${error.message}`);\r\n    }\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\nmain();\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"outDir\": \"dist\",\r\n    \"rootDir\": \"src\",\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true,\r\n    \"types\": [\"node\"]\r\n  },\r\n  \"include\": [\"src/**/*\"]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.)\r\n4. **Error Handling** — Are errors handled properly? Retries? Timeouts?\r\n5. **Code Quality** — Clean, readable, well-structured code?\r\n\r\n## Prompt-Specific Criteria\r\n\r\nIn addition to general criteria, evaluate each prompt-specific criterion listed in the \"Prompt-Specific Evaluation Criteria\" section (if provided). Each criterion is either MET (passed) or NOT MET (failed).\r\n\r\n## Scoring\r\n\r\nFor EACH criterion (general + prompt-specific), determine:\r\n- **passed*